CREATE TABLE IF NOT EXISTS scores(id TEXT PRIMARY KEY,name TEXT NOT NULL,mode TEXT NOT NULL,value REAL NOT NULL,vehicle TEXT NOT NULL,time INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS scores_mode ON scores(mode);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,name_key TEXT NOT NULL UNIQUE,token_hash TEXT NOT NULL UNIQUE,role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','owner')),created_at INTEGER NOT NULL);
